using System;using System.Reflection;using System.Collections.Concurrent;using TGLL;
class SonCapLimitTests{
 static void C(bool ok,string s){if(!ok)throw new Exception(s);}
 static int Main(){try{Run();return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Run(){NativeBackend.LogDirectory=System.IO.Path.GetFullPath("work/soncap153-logs");var jobs=(ConcurrentDictionary<string,NativeJob>)typeof(NativeBackend).GetField("jobs",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);var a=new NativeJob("synthetic.exe","a","",null,true);var b=new NativeJob("synthetic.exe","b","",null,true);foreach(var j in new[]{a,b}){jobs[j.Id]=j;j.SonCapEnabled=true;j.IzanamiEnabled=true;j.SonCapStage=1;j.IzanamiRoundEntered=true;j.State="opened";}NativeBackend.ConfigureSonCapTeams(new[]{a.Id,b.Id});DateTime t=DateTime.UtcNow;
  C(!NativeBackend.ObserveSonCapReturn(a,95,t),"in-instance map must not retry");C(NativeBackend.ObserveSonCapReturn(a,59,t),"return must wait for confirmation");C(a.SonCapStage==1,"return reset too soon");NativeBackend.ObserveSonCapReturn(a,59,t.AddSeconds(3));C(a.SonCapStage==-1&&a.IzanamiRequested&&!a.IzanamiRoundEntered&&!a.SonCapFinished&&a.SonCapStopPending,"stable return does not rearm entry");C(b.SonCapStage==1,"retry reset teammate still inside instance");
  C(NativeBackend.IsSonCapAttemptLimit("Người chơi GreenStar không đủ lượt tham gia Sơn cáp"),"named rejection not recognized");C(!NativeBackend.IsSonCapAttemptLimit("Không đủ lượt tham gia cấm thuật"),"wrong activity rejection accepted");C(!NativeBackend.IsSonCapAttemptLimit("Tham gia Sơn Cáp"),"ordinary menu accepted as rejection");
  a.IzanamiLimitArmed=true;a.IzanamiNoticeAt=t;C(NativeBackend.ObserveIzanamiAttemptLimit(a,"Người chơi GreenStar không đủ lượt tham gia Sơn cáp"),"armed entry rejection ignored");C(a.SonCapNoAttempts&&a.SonCapFinished&&!a.IzanamiRequested&&!b.SonCapFinished,"limit must end rejected outside account and preserve in-instance teammate");
  a.ProcessId=1;int closes=0;Action<NativeJob> close=j=>closes++;NativeBackend.SonCapCloseAfterEnabled=false;a.UpRequested=true;a.SonCapQueueOnly=true;NativeBackend.PulseSonCapLimitClose(close);C(closes==0,"queue close duplicated");a.SonCapQueueOnly=false;NativeBackend.PulseSonCapLimitClose(close);NativeBackend.PulseSonCapLimitClose(close);C(closes==0,"Up must keep exhausted account open");a.UpRequested=false;NativeBackend.PulseSonCapLimitClose(close);NativeBackend.PulseSonCapLimitClose(close);C(closes==1,"unprotected exhausted account must close exactly once");C(!b.SonCapFinished&&!b.CloseRequested,"in-instance peer affected");Console.WriteLine("PASS: named no-attempts keeps Up open and closes non-Up once, queue ownership and active-instance teammate preserved. No real game closed.");
 }
}
